arrays={s['id']:['data:image/png;base64,'+base64.b64encode((r/f[6:]).read_bytes()).decode() for f in s['frameFiles']] for s in m['states']}
html='''<!doctype html><html><meta charset="utf-8"><title>James arrival turn study 300</title><style>body{background:#303b40;color:#eee;font:16px sans-serif;margin:16px}button,input,select{margin:8px} .row{display:flex;align-items:end;gap:30px;height:200px} img{object-fit:contain}h2{font-size:18px}</style><h1>James arrival turn — provisional</h1><p>Bare-head source study. Old poses 0,1,5 retained. Carry/unload joins and helmet pending.</p><button id="play">Replay</button><button id="pause">Pause</button><label>Speed <select id="speed"><option value="1">Normal</option><option value="0.25">Quarter speed</option></select></label><label>Loop <input id="loop" type="checkbox"></label><input id="seek" type="range" min="0" max="5" value="0"><strong id="phase">Phase 0 / 5 — paused</strong><h2>Original turn</h2><div class="row" id="original"></div><h2>Revised study</h2><div class="row" id="candidate"></div><p>Same fixed pivot and original 800 ms timing. Display sizes: 148, 82, 54, 27 px standing ruler.</p><script>const sources=ARRAYS, clocks=[100,140,160,160,140,100], sizes=[148,82,54,27];let elapsed=0,last=0,running=false;const imgs={};for(const key of ['original','candidate']){imgs[key]=sizes.map(n=>{let im=document.createElement('img');im.width=256*n/148;im.height=256*n/148;document.getElementById(key).append(im);return im})}function show(i){for(const key of Object.keys(imgs))for(const im of imgs[key])im.src=sources[key][i];document.getElementById('seek').value=i;document.getElementById('phase').textContent='Phase '+i+' / 5 — '+(running?'playing':'paused')}function tick(t){if(running){elapsed+=(t-last)*Number(document.getElementById('speed').value);if(elapsed>=800){if(document.getElementById('loop').checked)elapsed%=800;else{elapsed=799.999;running=false}}let acc=0,i=0;while(i<5&&elapsed>=acc+clocks[i])acc+=clocks[i++];show(i)}last=t;requestAnimationFrame(tick)}document.getElementById('play').onclick=()=>{elapsed=0;running=true;last=performance.now();show(0)};document.getElementById('pause').onclick=()=>{running=false;show(Number(document.getElementById('seek').value))};document.getElementById('seek').oninput=e=>{running=false;elapsed=clocks.slice(0,Number(e.target.value)).reduce((a,b)=>a+b,0);show(Number(e.target.value))};show(0);requestAnimationFrame(tick);</script></html>'''.replace('ARRAYS',json.dumps(arrays))
(o/'playback-review.html').write_text(html,encoding='utf-8')
